package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;import android.graphics.Bitmap;import android.net.Uri;import android.os.*;import android.view.View;import android.widget.*;
final class ChatImageDraft extends LinearLayout {
 private static final java.util.concurrent.ExecutorService IO=java.util.concurrent.Executors.newFixedThreadPool(2);
 private Uri source;private String key="",path="";private Bitmap owned;private int ticket;private boolean decoding;private final ImageView preview;private final TextView state;private final Button remove;
 ChatImageDraft(Context c){super(c);setOrientation(VERTICAL);preview=new ImageView(c);preview.setScaleType(ImageView.ScaleType.FIT_CENTER);preview.setContentDescription("Prévia da imagem a enviar");addView(preview,new LayoutParams(-1,NativeSheet.dp(c,110)));LinearLayout row=new LinearLayout(c);row.setGravity(android.view.Gravity.CENTER_VERTICAL);state=NativeSheet.text(c,"",12,0xffc6b8ff);row.addView(state,new LayoutParams(0,-2,1));remove=new Button(c);remove.setText("Remover imagem");AppStyle.button(remove,false);remove.setOnClickListener(v->clear());row.addView(remove,new LayoutParams(-2,-2));addView(row);setVisibility(GONE);}
 void select(Uri uri){clear();source=uri;key=java.util.UUID.randomUUID().toString();int request=ticket;String owner=SessionPreferences.get(getContext()).getString("user_id","");setVisibility(VISIBLE);state.setText("Abrindo imagem…");decoding=true;IO.execute(()->{try{Bitmap image=ProfileImages.decode(getContext(),uri,5*1024*1024);new Handler(Looper.getMainLooper()).post(()->{if(request!=ticket||!owner.equals(SessionPreferences.get(getContext()).getString("user_id",""))){image.recycle();return;}owned=image;preview.setImageBitmap(image);decoding=false;state.setText("Imagem selecionada · legenda opcional");});}catch(Exception e){new Handler(Looper.getMainLooper()).post(()->{if(request!=ticket)return;source=null;decoding=false;state.setText("Não foi possível abrir. Escolha JPEG, PNG ou WebP de até 5 MB.");});}});}
 boolean selected(){return source!=null;}boolean ready(){return source!=null&&!decoding&&owned!=null;}Uri uri(){return source;}String key(){return key;}String path(){return path;}void uploaded(String value){path=value;}void busy(boolean value){remove.setEnabled(!value);}
 void clear(){ticket++;source=null;key="";path="";decoding=false;preview.setImageDrawable(null);if(owned!=null){owned.recycle();owned=null;}setVisibility(GONE);}
}
